export async function run(flags = {}) {
  const { readFolderWhere } = await import('../lib/frontmatter.mjs');
  const { getResearchVaultRoot } = await import('../lib/config.mjs');
  const reportsDir = join(getResearchVaultRoot(), '02_Reports');

