## Phase 6 — EOD Digest (Effort: M)

### Goal
Single markdown summary written to Research Spine at end of `bridge daily`:
- What signals fired today
- What got promoted to World_Machine
- What source gaps opened
- What is stale (unreviewed packets > N days)

### Files to create

**6a. `scripts/bridge/eod-digest.mjs`** — CREATE

```js
import { join } from 'node:path';
import { writeFileSync, mkdirSync } from 'node:fs';
import { getResearchVaultRoot, getSignalsDir } from '../lib/config.mjs';
import { readFolder, readFolderWhere } from '../lib/frontmatter.mjs';
import { today } from '../lib/markdown.mjs';

export async function writeEodDigest({ runId, results, gaps, wmResult, flags }) {
  const date = today();
  const dryRun = Boolean(flags?.['dry-run']);

  // 1. Signals fired today: read 06_Signals/ for today's date prefix
  const signalsDir = getSignalsDir();
  const todaySignals = (await readFolder(signalsDir, false))
    .filter(n => n.filename.startsWith(date));

  // 2. Promotions: wmResult.written[] from world-machine-flow
  const promoted = wmResult?.written ?? [];

  // 3. Source gaps: read the gap register or use gaps[] passed in
  const gapSummary = gaps.slice(0, 10); // top 10 by severity

  // 4. Stale unreviewed packets: review_status = 'unreviewed', age > 3 days
  const reportsDir = join(getResearchVaultRoot(), '02_Reports');
  const stale = (await readFolderWhere(reportsDir,
    d => d.review_status === 'unreviewed', true))
    .filter(n => daysBetween(n.data.date, date) > 3);

  // 5. Cadence task outcomes from results envelopes
  const failed = results.filter(e => !e.ok);
  const okCount = results.filter(e => e.ok).length;

  const md = buildDigestMarkdown({
    date, runId, todaySignals, promoted, gapSummary, stale, failed, okCount
  });

  const digestDir = join(getResearchVaultRoot(), '02_Reports', 'Briefings', 'EOD');
  const digestPath = join(digestDir, `${date}_EOD_Digest.md`);

  if (!dryRun) {
    mkdirSync(digestDir, { recursive: true });
    writeFileSync(digestPath, md, 'utf-8');
  }
  console.log(`[eod-digest] ${dryRun ? '[dry-run] ' : ''}wrote ${digestPath}`);
  return digestPath;
}

function buildDigestMarkdown({ date, runId, todaySignals, promoted, gapSummary, stale, failed, okCount }) {
  return [
    `---`,
    `type: eod_digest`,
    `date: ${date}`,
    `run_id: "${runId}"`,
    `---`,
    ``,
    `# EOD Digest — ${date}`,
    ``,
    `**Run:** \`${runId}\`  `,
    `**Tasks:** ${okCount} ok, ${failed.length} failed`,
    ``,
    `## Signals Fired Today (${todaySignals.length})`,
    ...todaySignals.map(s => `- [[${s.filename.replace('.md', '')}]]`),
    ``,
    `## Promoted to World_Machine (${promoted.length})`,
    ...promoted.map(p => `- ${p}`),
    ``,
    `## Source Gaps Opened (${gapSummary.length})`,
    ...gapSummary.map(g => `- **${g.severity}** — \`${g.source}\` (${g.count} failures, last: ${g.last_seen})`),
    ``,
    `## Stale Unreviewed Packets (${stale.length})`,
    ...stale.map(s => `- \`${s.data.packet_id ?? s.filename}\` — ${s.data.date} (${daysBetween(s.data.date, date)}d old)`),
    ``,
    `## Failed Tasks`,
    failed.length === 0 ? '_None_' : '',
    ...failed.map(e => `- \`${e.name}\`: ${e.errors[0]?.message ?? 'unknown error'}`),
    ``,
  ].join('\n');
}
```

### Dependencies
- Requires Phase 4 (gap data) and Phase 3 (packet_id in stale packets)
- Called from Phase 1 `bridge/daily.mjs` as final step

