```
export async function run(flags = {}) {
  const runId = `bridge-daily-${today()}-${Date.now()}`;
  const results = [];
  const gaps = [];

  // Step 1: Readiness preflight
  const { evaluateReadiness } = await import('../system/readiness.mjs');
  const readiness = await evaluateReadiness({ cadence: 'daily' });
  if (!readiness.ok && !flags['skip-readiness'] && !flags['allow-stale']) {
    console.warn('[bridge] Readiness preflight failed — use --allow-stale to continue');
    if (!flags['continue-on-error']) process.exit(1);
  }

  // Step 2: Run daily cadence (delegates to existing routine runner)
  const { run: runCadence } = await import('../routines/cadence.mjs');
  const cadenceResult = await runCadence('daily', { ...flags, 'skip-validate': true });
  results.push(...(cadenceResult?.envelopes ?? []));

  // Step 3: Research Spine promotion (existing puller)
  const { pull: spineFlow } = await import('../pullers/research-spine-flow.mjs');
  await spineFlow({ documents: 'daily-monitoring,daily-briefing,source-register', ...flags });

  // Step 4: World Machine bridge packets (existing puller)
  const { pull: wmFlow } = await import('../pullers/world-machine-flow.mjs');
  const wmResult = await wmFlow({ 'approved-only': true, ...flags });

  // Step 5: Packet quality validation (new — see Phase 5)
  if (!flags['skip-validate']) {
    const { validatePendingPackets } = await import('./packet-validator.mjs');
    const qv = await validatePendingPackets({ runId });
    gaps.push(...qv.gaps);
  }

  // Step 6: Write EOD digest (new — see Phase 6)
  const { writeEodDigest } = await import('./eod-digest.mjs');
  const digestPath = await writeEodDigest({ runId, results, gaps, wmResult, flags });

  console.log(`\n[bridge] Daily bridge complete. Digest: ${digestPath}`);
  return { ok: true, runId, wrote: [digestPath] };
}
```

