/**
 * source-gap-register.mjs — Scan run summaries and write a Source Gap Register.
 *
 * Reads <ResearchVaultRoot>/99_System/run_summaries/*.md, finds FAILED pullers,
 * computes severity, and writes a register to:
 *   <ResearchVaultRoot>/99_System/Source_Gap_Register.md
 *
 * Usage: node run.mjs system source-gap-register [--dry-run]
 */

import { readdirSync, readFileSync, mkdirSync, writeFileSync, existsSync } from 'fs';
import { join } from 'path';
import { getResearchVaultRoot } from '../lib/config.mjs';

// ── Severity thresholds ───────────────────────────────────────────────────────

const SEVERITY_ORDER = ['critical', 'high', 'medium', 'low'];

function computeSeverity(failureCount, ageDays) {
  if (failureCount >= 5 || ageDays >= 7) return 'critical';
  if (failureCount >= 3 || ageDays >= 3) return 'high';
  if (failureCount >= 2) return 'medium';
  return 'low';
}

// ── Run summary parsing ───────────────────────────────────────────────────────

/**
 * Extract the run date (YYYY-MM-DD) from a summary filename like 2026-05-13_09-30.md.
 * Returns null if the name doesn't match.
 */
function dateFromFilename(filename) {
  const m = filename.match(/^(\d{4}-\d{2}-\d{2})/);
  return m ? m[1] : null;
}

/**
 * Parse failed puller names from one run summary markdown file.
 * Looks for table rows where the Status cell is FAILED (or contains ❌/✗).
 * Returns an array of puller name strings.
 */
function parseFailedPullers(content) {
  const failed = [];
  for (const line of content.split('\n')) {
    // Match markdown table rows: | puller-name | FAILED | … |
    if (!line.startsWith('|')) continue;
    const cells = line.split('|').map(c => c.trim()).filter(Boolean);
    if (cells.length < 2) continue;
    const statusCell = cells[1];
    if (statusCell === 'FAILED' || statusCell.includes('❌') || statusCell.includes('✗')) {
      const name = cells[0];
      if (name && name !== '---' && name.toLowerCase() !== 'puller') {
        failed.push(name);
      }
    }
  }
  return failed;
}

// ── Core aggregation ──────────────────────────────────────────────────────────

/**
 * Scan all run summary files and aggregate per-puller failure stats.
 * Returns an array of gap records, sorted by severity then age_days desc.
 */
function buildGapRecords(summariesDir) {
  if (!existsSync(summariesDir)) {
    console.warn(`[source-gap-register] WARNING: run_summaries dir not found: ${summariesDir}`);
    return [];
  }

  const files = readdirSync(summariesDir)
    .filter(f => f.endsWith('.md'))
    .sort(); // lexicographic = chronological given YYYY-MM-DD_HH-MM naming

  /** @type {Map<string, { failure_count: number, first_failed: string, last_seen: string }>} */
  const byPuller = new Map();

  for (const filename of files) {
    const runDate = dateFromFilename(filename);
    if (!runDate) continue;

    const content = readFileSync(join(summariesDir, filename), 'utf-8');
    const failedNames = parseFailedPullers(content);

    for (const name of failedNames) {
      const existing = byPuller.get(name);
      if (!existing) {
        byPuller.set(name, { failure_count: 1, first_failed: runDate, last_seen: runDate });
      } else {
        byPuller.set(name, {
          failure_count: existing.failure_count + 1,
          first_failed: existing.first_failed < runDate ? existing.first_failed : runDate,
          last_seen: existing.last_seen > runDate ? existing.last_seen : runDate,
        });
      }
    }
  }

  const today = new Date().toISOString().slice(0, 10);

  const records = Array.from(byPuller.entries()).map(([puller, stats]) => {
    const ageDays = Math.round(
      (new Date(today) - new Date(stats.first_failed)) / (1000 * 60 * 60 * 24)
    );
    return Object.freeze({
      puller,
      failure_count: stats.failure_count,
      first_failed: stats.first_failed,
      last_seen: stats.last_seen,
      age_days: ageDays,
      severity: computeSeverity(stats.failure_count, ageDays),
    });
  });

  return records.sort((a, b) => {
    const si = SEVERITY_ORDER.indexOf(a.severity) - SEVERITY_ORDER.indexOf(b.severity);
    if (si !== 0) return si;
    return b.age_days - a.age_days;
  });
}

// ── Markdown builder ──────────────────────────────────────────────────────────

function buildRegisterMarkdown(records, updatedAt) {
  const frontmatter = ['---', 'type: source_gap_register', `updated: ${updatedAt}`, '---'].join('\n');

  const header = [
    '| Puller | Failures | First Failed | Last Seen | Age (days) | Severity |',
    '|---|---|---|---|---|---|',
  ];

  const rows = records.map(r =>
    `| ${r.puller} | ${r.failure_count} | ${r.first_failed} | ${r.last_seen} | ${r.age_days} | ${r.severity} |`
  );

  const tableSection = records.length > 0
    ? [...header, ...rows].join('\n')
    : '_No failed pullers found in run summaries._';

  return [frontmatter, '', '# Source Gap Register', '', tableSection, ''].join('\n');
}

// ── Public API ────────────────────────────────────────────────────────────────

export async function run(flags = {}) {
  const dryRun = Boolean(flags['dry-run'] ?? flags.dryRun);

  const researchRoot = getResearchVaultRoot();
  if (!researchRoot) {
    throw new Error('[source-gap-register] RESEARCH_VAULT_ROOT is not set and no default resolved.');
  }

  const summariesDir = join(researchRoot, '99_System', 'run_summaries');
  const records = buildGapRecords(summariesDir);

  const updatedAt = new Date().toISOString().slice(0, 10);
  const content = buildRegisterMarkdown(records, updatedAt);

  const outPath = join(researchRoot, '99_System', 'Source_Gap_Register.md');

  if (dryRun) {
    console.log(`[source-gap-register] DRY RUN — would write to: ${outPath}\n`);
    console.log(content);
    return;
  }

  mkdirSync(join(researchRoot, '99_System'), { recursive: true });
  writeFileSync(outPath, content, 'utf-8');

  console.log(`[source-gap-register] Wrote ${records.length} gap record(s) → ${outPath}`);
  if (records.length > 0) {
    const bySeverity = Object.fromEntries(
      SEVERITY_ORDER.map(s => [s, records.filter(r => r.severity === s).length])
    );
    console.log('[source-gap-register] Severity breakdown:', bySeverity);
  }
}

